var TPL={"sp":"<!DOCTYPE html><html lang=\"ja\"><head><meta name=\"robots\" content=\"noindex,nofollow\"><meta charset=\"utf-8\"><meta name=\"viewport\" content=\"width=device-width,initial-scale=1\"><title>/*TAG*/ 売上ダッシュボード（スマホ）</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"Noto Sans CJK JP\",\"Hiragino Sans\",\"Yu Gothic UI\",Meiryo,sans-serif;background:#0b0f1a;color:#e6ebf5;font-size:13px;\nbackground-image:radial-gradient(1200px 500px at 85% -10%,rgba(91,76,255,.20),transparent),radial-gradient(900px 400px at -10% 30%,rgba(0,212,255,.08),transparent)}\nheader{display:flex;align-items:center;justify-content:space-between;padding:16px 28px;border-bottom:1px solid #1c2336}\n.brand{display:flex;align-items:center;gap:12px}.brand b{font-size:16px;letter-spacing:.04em}\n.hex{width:28px;height:28px;border-radius:7px;background:conic-gradient(from 200deg,#00e0ff,#7b5cff,#ff4fd8,#00e0ff)}\n.tabs{display:flex;gap:4px;background:#121829;border:1px solid #1f2740;border-radius:10px;padding:3px}\n.tabs span{padding:6px 14px;border-radius:7px;color:#8b95b0}.tabs .on{background:#232c47;color:#fff}\n.meta{display:flex;gap:10px;align-items:center;color:#8b95b0;font-size:12px}\n.tag{border:1px solid #ffb547;color:#ffb547;border-radius:6px;padding:3px 9px;font-weight:700;font-size:11px;letter-spacing:.05em}\n.chip{background:#121829;border:1px solid #232c47;border-radius:8px;padding:6px 12px;color:#c9d1e6}\nmain{padding:20px 28px 26px}\n.g{display:grid;gap:14px;margin-bottom:14px}\n.k5{grid-template-columns:repeat(5,1fr)}\n.p{background:linear-gradient(180deg,rgba(23,30,50,.92),rgba(16,21,36,.92));border:1px solid #1f2740;border-radius:14px;padding:16px 18px;position:relative;overflow:hidden}\n.kl{color:#8b95b0;font-size:11.5px;letter-spacing:.06em}\n.kv{font-size:27px;font-weight:700;margin:6px 0 2px;font-variant-numeric:tabular-nums;letter-spacing:-.01em}\n.kv small{font-size:12px;color:#8b95b0;margin-left:3px;font-weight:500}\n.kd{font-size:11.5px;color:#8b95b0}\n.up{color:#3df5a7}.dn{color:#ff5c7a}\n.spark{position:absolute;right:14px;top:16px;width:96px;height:36px;opacity:.9}\n.glow{box-shadow:0 0 0 1px rgba(0,224,255,.35),0 10px 40px -10px rgba(0,224,255,.35)}\n.h{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px}\n.h h2{font-size:13.5px;font-weight:700;letter-spacing:.03em}.h .n{color:#6b7594;font-size:11px}\n.r1{grid-template-columns:1.7fr 1fr}\n.r2{grid-template-columns:repeat(4,1fr)}\n.r3{grid-template-columns:1.1fr 1fr}\n.svc .top{display:flex;justify-content:space-between;align-items:center}\n.svc .nm{font-weight:700;font-size:13px;display:flex;align-items:center;gap:8px}\n.svc .nm i{width:10px;height:10px;border-radius:50%}\n.svc .y{font-size:20px;font-weight:700}\n.svc .s{color:#8b95b0;font-size:11px;margin-top:2px}\n.svc .mini{height:78px;margin-top:8px}\n.svc.total{background:linear-gradient(135deg,rgba(123,92,255,.25),rgba(0,224,255,.10));border-color:#3a3f7a}\n.heat{width:100%;border-collapse:separate;border-spacing:3px}\n.heat th{color:#8b95b0;font-weight:500;font-size:11px;padding:4px 6px;text-align:center;white-space:nowrap}\n.heat th:first-child{text-align:left}\n.heat td{padding:7px 6px;border-radius:5px;text-align:center;font-size:11.5px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.heat td.n{text-align:left;background:none;color:#c9d1e6;font-size:12px}\n.heat td.t{background:#151c30;font-weight:700}\n.foot{color:#59627e;font-size:11px;text-align:right}\n\nbody{font-size:14px}header{padding:12px 14px;flex-wrap:wrap;gap:8px;position:sticky;top:0;z-index:5;background:rgba(11,15,26,.95);backdrop-filter:blur(6px)}\n.brand b{font-size:15px}main{padding:12px}\nselect{width:100%;min-height:46px;background:#121829;color:#e6ebf5;border:1px solid #2a3556;border-radius:10px;padding:8px 12px;font:inherit;font-size:16px}\n.k2{grid-template-columns:1fr 1fr;gap:10px}.p{padding:14px;border-radius:14px}.kv{font-size:22px}.kl{font-size:12px}.kd{font-size:11.5px}\n.est{color:#ffb547;font-size:10.5px;border:1px solid #ffb547;border-radius:5px;padding:0 5px;margin-left:4px}\n.sc{background:#121829;border:1px solid #1f2740;border-radius:12px;padding:12px;margin-bottom:8px}\n.sc .t{display:flex;justify-content:space-between;align-items:baseline}.sc .t b{font-size:15px}.sc .t span{color:#00e0ff;font-weight:700;font-size:16px}\n.sc .m{display:grid;grid-template-columns:repeat(3,1fr);gap:6px;margin-top:8px;color:#8b95b0;font-size:11.5px}.sc .m div b{display:block;color:#e6ebf5;font-size:14px}\n.sc .bar{height:6px;background:#1c2336;border-radius:3px;margin-top:8px}.sc .bar i{display:block;height:6px;border-radius:3px;background:linear-gradient(90deg,#00e0ff,#7b5cff)}\ndetails{background:linear-gradient(180deg,rgba(23,30,50,.92),rgba(16,21,36,.92));border:1px solid #1f2740;border-radius:14px;margin-bottom:10px}\nsummary{min-height:52px;display:flex;align-items:center;justify-content:space-between;padding:0 16px;font-weight:700;cursor:pointer;list-style:none}\nsummary::after{content:'＋';color:#00e0ff;font-size:18px}details[open] summary::after{content:'－'}\ndetails .in{padding:0 12px 14px;overflow-x:auto}\n.tabs2{display:flex;gap:6px;margin-bottom:10px}.tabs2 button{flex:1;min-height:44px;background:#121829;border:1px solid #232c47;color:#8b95b0;border-radius:10px;font:inherit}.tabs2 .on{background:#232c47;color:#fff;border-color:#3a4570}\n.note{color:#8b95b0;font-size:12px;line-height:1.8}.heat td,.heat th{font-size:10.5px;padding:5px 4px}\n.sd{background:#121829;border:1px solid #1f2740;border-radius:12px;margin-bottom:8px}.sd summary{min-height:56px;padding:8px 12px;display:block}.sd summary::after{content:none}\n.sd .tt{display:flex;justify-content:space-between}.sd .tt b{font-size:14.5px}.sd .tt span{color:#00e0ff;font-weight:700}\n.sd .cr{padding:8px 12px;border-top:1px solid #1c2336}.sd .cr .tt b{font-size:13px;font-weight:600}.sd .cr .tt span{color:#e6ebf5;font-weight:600}\n</style></head><body>\n<header><div class=\"brand\"><div class=\"hex\"></div><b>CARE<span style=\"color:#00e0ff\">METRICS</span></b><span style=\"color:#8b95b0;font-size:12px\">売上ダッシュボード ｜ /*TAG*/年度</span></div>\n<!--FYBAR--><div style=\"width:100%\"><select id=\"selM\"></select></div></header>\n<main>\n<div class=\"g k2\" id=\"kpis\"></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>月次売上・累計</h2><span class=\"n\">万円・橙＝推計</span></div><div style=\"height:230px\"><canvas id=\"trend\"></canvas></div></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>サービス構成比</h2><span class=\"n\" id=\"mixN\"></span></div><div style=\"height:250px\"><canvas id=\"mix\"></canvas></div></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>スタッフ別 稼働・売上</h2><span class=\"n\" id=\"stN\"></span></div>\n<div class=\"tabs2\" id=\"sortT\"><button data-k=\"y\" class=\"on\">売上順</button><button data-k=\"h\">時間順</button><button data-k=\"v\">件数順</button></div><div id=\"cards\"></div></div>\n<details id=\"scD\"><summary>スタッフ別 利用者別売上</summary><div class=\"in\"><div class=\"kd\" id=\"scSN\" style=\"margin-bottom:6px\"></div><div class=\"kd\" style=\"margin-bottom:8px\" id=\"scLeg\"></div><div id=\"scBody\"></div></div></details>\n<details><summary>スタッフ 12か月推移</summary><div class=\"in\"><select id=\"selStaff\"></select><div style=\"height:220px;margin-top:10px\"><canvas id=\"sy\"></canvas></div></div></details>\n<details><summary>サービス別 月次推移</summary><div class=\"in\"><div style=\"height:240px\"><canvas id=\"stack\"></canvas></div></div></details>\n<details><summary>居宅介護 内訳（身体・家事・通院）</summary><div class=\"in\"><div style=\"height:220px\"><canvas id=\"kyo\"></canvas></div></div></details>\n<details><summary>公費・利用者負担／利用者</summary><div class=\"in\" id=\"bill\"></div></details>\n<details><summary>利用者別 売上 上位20</summary><div class=\"in\"><div class=\"tabs2\" id=\"clT2\"><button data-k=\"m\" class=\"on\">当月</button><button data-k=\"c\">年度累計</button></div><div id=\"clCards\"></div></div></details>\n<details><summary>スタッフ × サービス 表</summary><div class=\"in\"><table class=\"heat\" id=\"heat\"></table></div></details>\n<details><summary>注記・算出方法</summary><div class=\"in note\" id=\"notes\"></div></details>\n</main>\n<script>/*CHARTJS*/</script>\n<script>const D=/*DATA*/;\nChart.defaults.animation=false;Chart.defaults.font.family='\"Noto Sans CJK JP\",\"Hiragino Sans\",\"Yu Gothic UI\",Meiryo,sans-serif';\nChart.defaults.color='#8b95b0';Chart.defaults.borderColor='#1c2336';\nconst COL={'身体介護':'#00e0ff','家事援助':'#3df5a7','通院等介助':'#4f8bff','居宅介護(内訳不明)':'#59627e','重度訪問介護':'#7b5cff','行動援護':'#ff4fd8','同行援護':'#ffb547','移動支援':'#f97066'};\nconst ML=D.months.map(m=>(+m.slice(5))+'月');\nconst EST=D.months.map(m=>D.est_months.includes(m));\nconst sum=a=>a.reduce((x,y)=>x+(y||0),0);\nconst man=v=>(v/10000).toLocaleString('ja-JP',{maximumFractionDigits:1});\nconst yen=v=>Math.round(v).toLocaleString('ja-JP');\nconst pct=v=>v==null||!isFinite(v)?'—':(v>=0?'+':'')+(v*100).toFixed(1)+'%';\nconst cls=v=>v==null||!isFinite(v)?'':(v>=0?'up':'dn');\nconst S={m:D.months.length-1,svc:'all'};\nfunction salesArr(svc){return svc==='all'?D.sales_m:D.sales_ms[svc]}\nfunction usersArr(svc){return svc==='all'?D.users:D.users_svc[svc]}\nfunction visitArr(svc){const ks=svc==='all'?D.svcB:[svc];return D.months.map((_,i)=>sum(ks.map(k=>D.visit_s[k][i])))}\nfunction hourArr(svc){const ks=svc==='all'?D.svcB:[svc];return D.months.map((_,i)=>sum(ks.map(k=>D.hour_s[k][i])))}\nfunction prevArr(){return S.svc==='all'?D.prev:(D.prev_ms[S.svc]||D.months.map(()=>null))}\nfunction prevYoY(i){const p=prevArr()[i];if(p==null||!p)return null;return salesArr(S.svc)[i]/p-1}\nfunction cumYoY(i){const p=prevArr(),s=salesArr(S.svc);let a=0,b=0;for(let j=0;j<=i;j++){if(p[j]==null)return null;a+=s[j];b+=p[j]}return b?a/b-1:null}\nfunction pvArr(kind){if(S.svc==='all')return kind==='v'?D.prev_vis:D.prev_hrs;const o=kind==='v'?D.prev_vis_s:D.prev_hrs_s;return o&&o[S.svc]?o[S.svc]:D.months.map(()=>null)}\nconst yo=(c,p)=>p==null||!p?null:c/p-1;\nfunction staffYoY(n,i,k){const p=D.prev_staff[n];return p?yo(k==='y'?sum(D.svcs.map(s=>D.staff[n].y[s][i])):k==='h'?sum(D.svcB.map(s=>D.staff[n].h[s][i])):0,p[k][i]):null}\nfunction kpis(){const i=S.m,s=salesArr(S.svc),cur=s[i],pm=i>0?s[i-1]:null,cum=sum(s.slice(0,i+1));\n const u=usersArr(S.svc)[i],v=visitArr(S.svc)[i],h=hourArr(S.svc)[i];\n const k=D.kouhi[i],f=D.futan[i];\n return {cur,mom:pm?cur/pm-1:null,cum,yoy:prevYoY(i),cyoy:cumYoY(i),users:u,visits:v,hours:h,per:u?cur/u:0,k,f,est:EST[i],\n  vy:yo(v,pvArr('v')[i]),hy:yo(h,pvArr('h')[i]),vm:i>0?v/visitArr(S.svc)[i-1]-1:null,hm:i>0?h/hourArr(S.svc)[i-1]-1:null,um:i>0?u-usersArr(S.svc)[i-1]:null}}\nfunction staffRows(i,svc){return Object.entries(D.staff).map(([n,o])=>{const ks=svc==='all'?D.svcB:[svc],ys=svc==='all'?D.svcs:(D.svcs.includes(svc)?[svc]:[]);\n const h=sum(ks.map(k=>o.h[k][i])),v=sum(ks.map(k=>o.v[k][i])),y=sum(ys.map(k=>o.y[k][i])),mh=o.h['移動支援'][i];\n return {n,h,v,y,mh,ph:h>0?y/h:0}}).filter(r=>r.h>0||r.y>0).sort((a,b)=>b.y-a.y||b.h-a.h)}\nfunction staffYear(n){const o=D.staff[n];return {h:D.months.map((_,i)=>sum(D.svcB.map(k=>o.h[k][i]))),v:D.months.map((_,i)=>sum(D.svcB.map(k=>o.v[k][i]))),\n y:D.months.map((_,i)=>sum(D.svcs.map(k=>o.y[k][i])))}}\nconst charts={};function mk(id,cfg){if(charts[id])charts[id].destroy();charts[id]=new Chart(document.getElementById(id),cfg)}\nfunction trendCfg(){const s=salesArr(S.svc);let c=0;const cum=s.map(v=>c+=v);\n return {data:{labels:ML.map((l,i)=>EST[i]?l+'(推計)':l),datasets:[\n {type:'bar',label:'月間売上(万円)',data:s.map(v=>v/1e4),backgroundColor:s.map((_,i)=>EST[i]?'rgba(255,181,71,.45)':(i===S.m?'#00e0ff':'rgba(0,224,255,.45)')),borderColor:s.map((_,i)=>EST[i]?'#ffb547':'transparent'),borderWidth:1,borderDash:[4,3],yAxisID:'y',order:2},\n ...(D.prior_fy?[{type:'line',label:'前年同月(万円)',data:prevArr().map(v=>v==null?null:v/1e4),borderColor:'#ffb547',borderDash:[5,4],pointRadius:2,yAxisID:'y',order:0}]:[]),{type:'line',label:'年度累計(万円)',data:cum.map(v=>v/1e4),borderColor:'#7b5cff',backgroundColor:'#7b5cff',pointRadius:2,tension:.3,yAxisID:'y1',order:1}]},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{y:{position:'left',grid:{color:'#1c2336'}},y1:{position:'right',grid:{display:false}}}}}}\nfunction mixCfg(){const i=S.m;return {type:'doughnut',data:{labels:D.svcs,datasets:[{data:D.svcs.map(s=>D.sales_ms[s][i]),backgroundColor:D.svcs.map(s=>COL[s]),borderColor:'#101524',borderWidth:2}]},\n options:{maintainAspectRatio:false,cutout:'62%',plugins:{legend:{position:'bottom',labels:{boxWidth:10}},tooltip:{callbacks:{label:c=>c.label+' '+man(c.raw)+'万円 ('+(c.raw/sum(c.dataset.data)*100).toFixed(1)+'%)'}}}}}}\nfunction stackCfg(){return {type:'bar',data:{labels:ML,datasets:D.svcs.map(s=>({label:s,data:D.sales_ms[s].map(v=>v/1e4),backgroundColor:COL[s]}))},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{x:{stacked:true},y:{stacked:true,title:{display:true,text:'万円'}}}}}}\nfunction kyoCfg(){const c={'身体':'#00e0ff','家事':'#3df5a7','通院':'#ffb547'};return {type:'bar',data:{labels:ML,datasets:Object.keys(D.kyo_sub).map(s=>({label:s,data:D.kyo_sub[s].map(v=>v/1e4),backgroundColor:c[s]}))},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{x:{stacked:true},y:{stacked:true,title:{display:true,text:'万円'}}}}}}\nfunction clientTop(i,cum,svc){const r=Object.entries(D.clients).map(([k,o])=>{const by={};D.svcs.forEach(s=>{by[s]=cum?sum(o.y[s].slice(0,i+1)):o.y[s][i]});\n const tot=svc==='all'||!D.svcs.includes(svc)?sum(Object.values(by)):by[svc];const p=D.prev_clients[k];\n const pv=p?(cum?(p.slice(0,i+1).some(v=>v==null)?null:sum(p.slice(0,i+1))):p[i]):null;\n return {k,n:o.n,by,tot,yoy:(svc==='all'&&pv)?tot/pv-1:null}}).filter(x=>x.tot>0).sort((a,b)=>b.tot-a.tot);return r.slice(0,20)}\nfunction clientCfg(rows){return {type:'bar',data:{labels:rows.map((r,j)=>(j+1)+'. '+r.n),datasets:D.svcs.map(s=>({label:s,data:rows.map(r=>r.by[s]/1e4),backgroundColor:COL[s]}))},\n options:{indexAxis:'y',maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}},tooltip:{callbacks:{footer:it=>{const r=rows[it[0].dataIndex];return '計 '+man(r.tot)+'万円　前年比 '+pct(r.yoy)}}}},\n scales:{x:{stacked:true,title:{display:true,text:'万円'}},y:{stacked:true,ticks:{autoSkip:false,font:{size:10.5}}}}}}}\nfunction muniCfg(){const i=S.m,e=Object.entries(D.muni).map(([k,v])=>[k,v[i]]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);\n return {type:'bar',data:{labels:e.map(x=>x[0]),datasets:[{label:'売上(万円)',data:e.map(x=>x[1]/1e4),backgroundColor:'#7b5cff'}]},options:{indexAxis:'y',maintainAspectRatio:false,plugins:{legend:{display:false}}}}}\nfunction staffYearCfg(n){const o=staffYear(n),p=D.prev_staff[n];return {data:{labels:ML,datasets:[...(p?[{type:'line',label:'前年 売上(万円)',data:p.y.map(v=>v/1e4),borderColor:'#ffb547',borderDash:[5,4],yAxisID:'y'}]:[]),{type:'bar',label:'推計売上(万円)',data:o.y.map(v=>v/1e4),backgroundColor:'rgba(0,224,255,.55)',yAxisID:'y'},\n {type:'line',label:'稼働時間(h)',data:o.h,borderColor:'#ff4fd8',backgroundColor:'#ff4fd8',tension:.3,yAxisID:'y1'}]},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{y:{position:'left'},y1:{position:'right',grid:{display:false}}}}}}\nfunction heatHTML(i,metric){const rows=staffRows(i,'all');let mx=0;const cell=(n,s)=>metric==='y'?(D.staff[n].y[s]?D.staff[n].y[s][i]:null):D.staff[n].h[s][i];\n rows.forEach(r=>D.svcB.forEach(s=>{const v=cell(r.n,s);if(v>mx)mx=v}));\n let h='<tr><th>スタッフ</th>'+D.svcB.map(s=>'<th>'+s+'</th>').join('')+'<th>計</th></tr>';\n rows.forEach(r=>{h+='<tr><td class=\"n\">'+r.n+'</td>'+D.svcB.map(s=>{const v=cell(r.n,s);if(v==null)return '<td style=\"color:#59627e\">データなし</td>';\n  const a=mx?v/mx:0;return '<td style=\"background:rgba(0,224,255,'+(0.06+a*0.7).toFixed(2)+');color:'+(a>.5?'#04121a':'#c9d1e6')+'\">'+(v?(metric==='y'?man(v):v.toFixed(1)):'')+'</td>'}).join('')+\n  '<td class=\"t\">'+(metric==='y'?man(r.y):r.h.toFixed(1))+'</td></tr>'});return h}\nconst NOTES=()=>`令和${D.fy-2018}年度版。${D.missing&&D.missing.length?'<b>未登録の月: '+D.missing.join('・')+'（0円で表示）。</b>':''}${D.months.length<12?'<b>年度途中：'+D.months[0]+'〜'+D.months.at(-1)+'の'+D.months.length+'か月分のみ（前年比も同月までで比較）。</b>':''}売上＝請求提出実績①の総費用（提供月基準・小計行除外）。${D.fy}年度（${D.months[0]}〜${D.months[D.months.length-1]}提供分）、年度合計 ${yen(sum(D.sales_m))}円。\n${D.est_months.map(m=>(+m.slice(5))+'月').join('・')}提供分は①未収録のため、③単位数×実績単価（障害福祉${D.ypu.toFixed(2)}円/単位、移動支援${D.ypu_svc&&D.ypu_svc['移動支援']?D.ypu_svc['移動支援'].toFixed(2):'—'}円/単位）で<b>推計</b>。\n①の重複疑い${D.ainfo.dup.groups}組は、返戻・再請求（金額訂正含む）とみなし、各組で最新の提出月の行のみ採用（${D.ainfo.dup.dropped}行除外）。\n各月は「提供月」単位でアップロードされたデータ。月遅れ請求・返戻は、その提供月を再アップロードすると反映。\nスタッフ別売上は推計：③の日別単位（加算は同月の基本行へ比例配分）を②の訪問へ「日付＋利用者＋サービス」で割当（${(D.alloc.exact/D.alloc.total*100).toFixed(1)}%）、不一致分は同月同利用者同サービスの時間比で按分（${(D.alloc.fallback/D.alloc.total*100).toFixed(1)}%）、未割当${(D.alloc.unalloc/D.alloc.total*100).toFixed(1)}%（訪問記録の無い利用者分）。\n居宅介護は①の金額を③の単位比（加算は基本行に比例配分）で身体介護・家事援助・通院等介助（通院は身体伴う/伴わないを合算）に分割。移動支援は移動支援の請求提出実績（総費用・提供月基準）を売上とし、③移動支援明細の日別単位で訪問に割当。時間あたり売上は移動支援の時間を含む。${D.prior_fy?'前年比は'+D.prior_fy+'年度実績（同ダッシュボード方式で算出）との比較。':''}訪問件数・時間は実施済のみ（9月は状況欄なしのため全件）、事務・研修・会議・同行研修・テスト入力は除外。`;\n// ===== スタッフ別 利用者別売上 =====\nconst SCY=r=>sum(r.slice(6));\nfunction scGroups(i,annual){const m={};D.sc.forEach(r=>{if(annual?r[0]>i:r[0]!==i)return;const g=m[r[1]]||(m[r[1]]={n:r[1],cl:{}});\n const c=g.cl[r[2]]||(g.cl[r[2]]={code:r[2],n:D.cnames[r[2]]||r[2],v:0,h:0,hm:0,by:D.svcs.map(()=>0),pv:0,pvok:true});\n c.v+=r[3];c.h+=r[4];c.hm+=r[5];r.slice(6).forEach((y,j)=>c.by[j]+=y);});\n return Object.values(m).map(g=>{const cl=Object.values(g.cl).map(c=>{c.y=sum(c.by);c.ph=c.h>0&&c.y?c.y/c.h:0;\n   if(annual){let p=0,ok=false;for(let j=0;j<=i;j++){const q=D.prev_sc[j+'|'+g.n+'|'+c.code];if(q){p+=q[0];ok=true}}c.yoy=ok&&p?c.y/p-1:null}\n   else{const q=D.prev_sc[i+'|'+g.n+'|'+c.code];c.yoy=q&&q[0]?c.y/q[0]-1:null}return c}).sort((a,b)=>b.y-a.y||b.h-a.h);\n  const t={n:g.n,cl,y:sum(cl.map(c=>c.y)),v:sum(cl.map(c=>c.v)),h:sum(cl.map(c=>c.h)),hm:sum(cl.map(c=>c.hm))};t.ph=t.h>0?t.y/t.h:0;\n  t.yoy=annual?null:staffYoY(g.n,i,'y');if(annual&&D.prev_staff[g.n]){t.yoy=yo(t.y,sum(D.prev_staff[g.n].y.slice(0,i+1)))}return t}).sort((a,b)=>b.y-a.y||b.h-a.h)}\nconst svBar=(by,w)=>{const t=sum(by)||1;return `<div style=\"display:flex;width:${w}px;height:8px;border-radius:4px;overflow:hidden;background:#1c2336\">${D.svcs.map((s,j)=>`<i style=\"width:${by[j]/t*100}%;background:${COL[s]}\"></i>`).join('')}</div>`};\nconst svLegend=()=>D.svcs.map(s=>`<span style=\"white-space:nowrap\"><span style=\"display:inline-block;width:8px;height:8px;border-radius:50%;background:${COL[s]};margin-right:3px\"></span>${s}</span>`).join('　');\n\nlet SK='y',CL='m';const selM=document.getElementById('selM'),selSt=document.getElementById('selStaff');\nD.months.forEach((m,i)=>selM.add(new Option(m.replace('-','年')+'月 提供分'+(EST[i]?'（推計）':''),i)));selM.value=S.m;selM.onchange=()=>{S.m=+selM.value;render()};\nObject.keys(D.staff).forEach(n=>selSt.add(new Option(n,n)));selSt.onchange=()=>mk('sy',staffYearCfg(selSt.value));\ndocument.querySelectorAll('#sortT button').forEach(b=>b.onclick=()=>{SK=b.dataset.k;document.querySelectorAll('#sortT button').forEach(x=>x.classList.toggle('on',x===b));render()});\ndocument.querySelectorAll('#clT2 button').forEach(b=>b.onclick=()=>{CL=b.dataset.k;document.querySelectorAll('#clT2 button').forEach(x=>x.classList.toggle('on',x===b));render()});\nconst card=(l,v,d,g)=>`<div class=\"p${g?' glow':''}\"><div class=\"kl\">${l}</div><div class=\"kv\">${v}</div><div class=\"kd\">${d}</div></div>`;\nfunction render(){const k=kpis(),E=k.est?'<span class=\"est\">推計</span>':'';\n document.getElementById('kpis').innerHTML=card('月間売上'+E,man(k.cur)+'<small>万円</small>','前年比 '+pct(k.yoy),1)+\n card('前月比',`<span class=\"${cls(k.mom)}\">${pct(k.mom)}</span>`,'前月 '+(S.m?man(D.sales_m[S.m-1]):'—')+'万円')+\n card('年度累計',man(k.cum)+'<small>万円</small>','前年比 '+pct(k.cyoy))+card('実利用者数',k.users+'<small>人</small>','1人 '+man(k.per)+'万円')+\n card('訪問件数',k.visits.toLocaleString()+'<small>件</small>','前月比 '+pct(k.vm)+' / 前年比 '+pct(k.vy))+card('提供時間',Math.round(k.hours).toLocaleString()+'<small>h</small>','前月比 '+pct(k.hm)+' / 前年比 '+pct(k.hy));\n const t=trendCfg();t.options.plugins.legend.display=false;t.options.scales.y1.display=false;t.data.labels=ML;mk('trend',t);\n mk('mix',mixCfg());document.getElementById('mixN').textContent=ML[S.m];\n const rows=staffRows(S.m,'all').sort((a,b)=>b[SK]-a[SK]),mx=Math.max(...rows.map(r=>r[SK]),1);\n document.getElementById('stN').textContent=ML[S.m]+'・売上は推計';\n document.getElementById('cards').innerHTML=rows.map((r,i)=>`<div class=\"sc\"><div class=\"t\"><b>${i+1}. ${r.n}</b><span>${man(r.y)}万円</span></div>\n <div class=\"m\"><div>稼働時間<b>${r.h.toFixed(1)}h</b></div><div>訪問件数<b>${r.v}件</b></div><div>時間あたり<b>${r.ph?yen(r.ph)+'円':'—'}</b></div></div><div class=\"kd\" style=\"margin-top:6px\">売上前年比 <b class=\"${cls(staffYoY(r.n,S.m,'y'))}\">${pct(staffYoY(r.n,S.m,'y'))}</b>　時間前年比 <b class=\"${cls(staffYoY(r.n,S.m,'h'))}\">${pct(staffYoY(r.n,S.m,'h'))}</b></div>\n <div class=\"bar\"><i style=\"width:${r[SK]/mx*100}%\"></i></div>${r.mh?`<div class=\"kd\" style=\"margin-top:6px\">うち移動支援 ${r.mh.toFixed(1)}h</div>`:''}</div>`).join('');\n if(!selSt.value)selSt.value=rows[0].n;mk('sy',staffYearCfg(selSt.value));\n mk('stack',stackCfg());mk('kyo',kyoCfg());{const cr=clientTop(S.m,CL==='c','all'),mx=cr.length?cr[0].tot:1;document.getElementById('clCards').innerHTML='<div class=\"kd\" style=\"margin-bottom:8px\">'+(CL==='c'?ML[0]+'〜'+ML[S.m]+' 累計':ML[S.m]+'提供分')+'</div>'+cr.map((r,j)=>`<div class=\"sc\"><div class=\"t\"><b>${j+1}. ${r.n}</b><span>${man(r.tot)}万円</span></div>\n <div style=\"display:flex;height:8px;border-radius:4px;overflow:hidden;margin-top:8px;width:${r.tot/mx*100}%\">${D.svcs.map(s=>`<i style=\"width:${r.by[s]/r.tot*100}%;background:${COL[s]}\"></i>`).join('')}</div>\n <div class=\"kd\" style=\"margin-top:6px\">${D.svcs.filter(s=>r.by[s]>0).map(s=>`<span style=\"color:${COL[s]}\">●</span>${s} ${man(r.by[s])}万`).join('　')}　前年比 <b class=\"${cls(r.yoy)}\">${pct(r.yoy)}</b></div></div>`).join('')}\n document.getElementById('bill').innerHTML=k.est?'<div class=\"note\">推計月のため公費・負担の内訳はありません。</div>':\n `<div class=\"g k2\" style=\"margin:0\">${card('公費（市町村請求）',man(k.k)+'<small>万円</small>',(k.k/(k.k+k.f)*100).toFixed(1)+'%')}${card('利用者負担',man(k.f)+'<small>万円</small>',(k.f/(k.k+k.f)*100).toFixed(1)+'%')}</div>`;\n document.getElementById('heat').innerHTML=heatHTML(S.m,'h');\n {const G=scGroups(S.m,false);document.getElementById('scSN').textContent=ML[S.m]+'提供分'+(EST[S.m]?'（推計）':'')+'・加算込み推計売上・タップで利用者一覧';document.getElementById('scLeg').innerHTML=svLegend();\n document.getElementById('scBody').innerHTML=G.map((g,gi)=>`<details class=\"sd\"><summary><div class=\"tt\"><b>${gi+1}. ${g.n}</b><span>${man(g.y)}万円</span></div>\n <div class=\"kd\">${g.v}件・${g.h.toFixed(1)}h・${g.ph?yen(g.ph)+'円/h':'—'}・前年同月比 <b class=\"${cls(g.yoy)}\">${pct(g.yoy)}</b>・利用者${g.cl.length}名 ▼</div></summary>\n ${g.cl.map(c=>`<div class=\"cr\"><div class=\"tt\"><b>${c.n}</b><span>${man(c.y)}万円</span></div><div style=\"margin:5px 0\">${svBar(c.by,200)}</div>\n <div class=\"kd\">${c.v}件・${c.h.toFixed(1)}h${c.hm?'（移動'+c.hm.toFixed(1)+'h）':''}・${c.ph?yen(c.ph)+'円/h':'—'}・前年比 <b class=\"${cls(c.yoy)}\">${pct(c.yoy)}</b></div></div>`).join('')}</details>`).join('')}\n document.getElementById('notes').innerHTML=NOTES().replace(/\\n/g,'<br><br>');}\nrender();window.__ready=true;\n</script></body></html>\n","pc":"<!DOCTYPE html><html lang=\"ja\"><head><meta name=\"robots\" content=\"noindex,nofollow\"><meta charset=\"utf-8\"><title>/*TAG*/ 売上ダッシュボード（PC）</title>\n<style>\n*{box-sizing:border-box;margin:0;padding:0}\nbody{font-family:\"Noto Sans CJK JP\",\"Hiragino Sans\",\"Yu Gothic UI\",Meiryo,sans-serif;background:#0b0f1a;color:#e6ebf5;font-size:13px;\nbackground-image:radial-gradient(1200px 500px at 85% -10%,rgba(91,76,255,.20),transparent),radial-gradient(900px 400px at -10% 30%,rgba(0,212,255,.08),transparent)}\nheader{display:flex;align-items:center;justify-content:space-between;padding:16px 28px;border-bottom:1px solid #1c2336}\n.brand{display:flex;align-items:center;gap:12px}.brand b{font-size:16px;letter-spacing:.04em}\n.hex{width:28px;height:28px;border-radius:7px;background:conic-gradient(from 200deg,#00e0ff,#7b5cff,#ff4fd8,#00e0ff)}\n.tabs{display:flex;gap:4px;background:#121829;border:1px solid #1f2740;border-radius:10px;padding:3px}\n.tabs span{padding:6px 14px;border-radius:7px;color:#8b95b0}.tabs .on{background:#232c47;color:#fff}\n.meta{display:flex;gap:10px;align-items:center;color:#8b95b0;font-size:12px}\n.tag{border:1px solid #ffb547;color:#ffb547;border-radius:6px;padding:3px 9px;font-weight:700;font-size:11px;letter-spacing:.05em}\n.chip{background:#121829;border:1px solid #232c47;border-radius:8px;padding:6px 12px;color:#c9d1e6}\nmain{padding:20px 28px 26px}\n.g{display:grid;gap:14px;margin-bottom:14px}\n.k5{grid-template-columns:repeat(5,1fr)}\n.p{background:linear-gradient(180deg,rgba(23,30,50,.92),rgba(16,21,36,.92));border:1px solid #1f2740;border-radius:14px;padding:16px 18px;position:relative;overflow:hidden}\n.kl{color:#8b95b0;font-size:11.5px;letter-spacing:.06em}\n.kv{font-size:27px;font-weight:700;margin:6px 0 2px;font-variant-numeric:tabular-nums;letter-spacing:-.01em}\n.kv small{font-size:12px;color:#8b95b0;margin-left:3px;font-weight:500}\n.kd{font-size:11.5px;color:#8b95b0}\n.up{color:#3df5a7}.dn{color:#ff5c7a}\n.spark{position:absolute;right:14px;top:16px;width:96px;height:36px;opacity:.9}\n.glow{box-shadow:0 0 0 1px rgba(0,224,255,.35),0 10px 40px -10px rgba(0,224,255,.35)}\n.h{display:flex;justify-content:space-between;align-items:baseline;margin-bottom:10px}\n.h h2{font-size:13.5px;font-weight:700;letter-spacing:.03em}.h .n{color:#6b7594;font-size:11px}\n.r1{grid-template-columns:1.7fr 1fr}\n.r2{grid-template-columns:repeat(4,1fr)}\n.r3{grid-template-columns:1.1fr 1fr}\n.svc .top{display:flex;justify-content:space-between;align-items:center}\n.svc .nm{font-weight:700;font-size:13px;display:flex;align-items:center;gap:8px}\n.svc .nm i{width:10px;height:10px;border-radius:50%}\n.svc .y{font-size:20px;font-weight:700}\n.svc .s{color:#8b95b0;font-size:11px;margin-top:2px}\n.svc .mini{height:78px;margin-top:8px}\n.svc.total{background:linear-gradient(135deg,rgba(123,92,255,.25),rgba(0,224,255,.10));border-color:#3a3f7a}\n.heat{width:100%;border-collapse:separate;border-spacing:3px}\n.heat th{color:#8b95b0;font-weight:500;font-size:11px;padding:4px 6px;text-align:center;white-space:nowrap}\n.heat th:first-child{text-align:left}\n.heat td{padding:7px 6px;border-radius:5px;text-align:center;font-size:11.5px;font-variant-numeric:tabular-nums;white-space:nowrap}\n.heat td.n{text-align:left;background:none;color:#c9d1e6;font-size:12px}\n.heat td.t{background:#151c30;font-weight:700}\n.foot{color:#59627e;font-size:11px;text-align:right}\n\n.k4{grid-template-columns:repeat(4,1fr)} .r2b{grid-template-columns:1fr 1fr} .r1{grid-template-columns:1.7fr 1fr}\nselect{background:#121829;color:#e6ebf5;border:1px solid #232c47;border-radius:8px;padding:6px 10px;font:inherit}\n.kd b{font-weight:600}.est{color:#ffb547;font-size:11px;border:1px solid #ffb547;border-radius:5px;padding:1px 6px;margin-left:6px}\n.seg{display:inline-flex;background:#121829;border:1px solid #232c47;border-radius:8px;padding:2px}.seg button{background:none;border:0;color:#8b95b0;padding:4px 10px;border-radius:6px;cursor:pointer;font:inherit}.seg .on{background:#232c47;color:#fff}\ntable.st{width:100%;border-collapse:collapse;font-variant-numeric:tabular-nums}\ntable.st th{color:#8b95b0;font-weight:500;font-size:11px;text-align:left;padding:6px 8px;border-bottom:1px solid #1f2740}\ntable.st td{padding:6px 8px;border-bottom:1px solid #161d31;font-size:12px}\ntable.st tr{cursor:pointer}table.st tr.sel td{background:rgba(0,224,255,.08)}\n.bar{display:flex;align-items:center;gap:8px}.bar i{display:block;height:8px;border-radius:4px}.bar span{min-width:64px;text-align:right}\n.note{color:#8b95b0;font-size:11.5px;line-height:1.8}\n.scb{border:1px solid #1f2740;border-radius:12px;margin-bottom:8px;background:#0f1424}.scb summary{display:grid;grid-template-columns:24px 1.4fr 1fr .7fr .7fr .9fr .7fr;align-items:center;gap:8px;padding:10px 12px;cursor:pointer;list-style:none;font-variant-numeric:tabular-nums}\n.scb summary b{font-size:13.5px}.scb .r{display:grid;grid-template-columns:24px 1.4fr 1fr .7fr .7fr .9fr .7fr;gap:8px;align-items:center;padding:5px 12px;border-top:1px solid #161d31;font-size:12px;font-variant-numeric:tabular-nums}\n.scb .hd{color:#8b95b0;font-size:11px}.yb{display:flex;align-items:center;gap:6px}.yb i{height:7px;border-radius:4px;background:#00e0ff;display:block}\n</style></head><body>\n<header><div class=\"brand\"><div class=\"hex\"></div><b>CARE<span style=\"color:#00e0ff\">METRICS</span></b><span style=\"color:#8b95b0\">｜ 売上ダッシュボード ｜ /*TAG*/年度</span></div>\n<div class=\"meta\">提供月 <select id=\"selM\"></select> サービス <select id=\"selS\"></select><span class=\"chip\" id=\"fyChip\"></span></div></header><div style=\"padding:10px 20px 0;max-width:900px\"><!--FYBAR--></div>\n<main>\n<div class=\"g k4\" id=\"kpis\"></div>\n<div class=\"g r1\">\n<div class=\"p\"><div class=\"h\"><h2>月次売上 ＋ 年度累計</h2><span class=\"n\">棒：月間売上 ／ 線：累計（右軸）／ 橙枠＝推計</span></div><div style=\"height:290px\"><canvas id=\"trend\"></canvas></div></div>\n<div class=\"p\"><div class=\"h\"><h2>サービス構成比</h2><span class=\"n\" id=\"mixN\"></span></div><div style=\"height:290px\"><canvas id=\"mix\"></canvas></div></div></div>\n<div class=\"g r2b\">\n<div class=\"p\"><div class=\"h\"><h2>サービス別 月次売上（積み上げ）</h2><span class=\"n\">万円</span></div><div style=\"height:260px\"><canvas id=\"stack\"></canvas></div></div>\n<div class=\"p\"><div class=\"h\"><h2>居宅介護 内訳（身体・家事・通院）</h2><span class=\"n\">③単位を①金額で按分・万円</span></div><div style=\"height:260px\"><canvas id=\"kyo\"></canvas></div></div></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>スタッフ ランキング</h2><span class=\"seg\" id=\"rkSeg\"><button data-k=\"h\" class=\"on\">稼働時間</button><button data-k=\"v\">訪問件数</button><button data-k=\"y\">推計売上</button></span></div><div style=\"height:380px\"><canvas id=\"rank\"></canvas></div></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>利用者別 売上 上位20</h2><span><span class=\"n\" id=\"clN\"></span> <span class=\"seg\" id=\"clSeg\"><button data-k=\"m\" class=\"on\">当月</button><button data-k=\"c\">年度累計</button></span></span></div>\n<div style=\"display:grid;grid-template-columns:1.2fr 1fr;gap:16px\"><div style=\"height:560px\"><canvas id=\"cl\"></canvas></div><div><table class=\"st\" id=\"clT\"></table></div></div></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>スタッフ別 月次稼働・売上</h2><span class=\"n\" id=\"stN\"></span></div>\n<div style=\"display:grid;grid-template-columns:1.25fr 1fr;gap:16px\">\n<div><table class=\"st\" id=\"stT\"></table></div>\n<div><div class=\"h\"><h2 id=\"sySel\">—</h2><span class=\"n\">12か月推移（行をクリックで切替）</span></div><div style=\"height:300px\"><canvas id=\"sy\"></canvas></div>\n<table class=\"st\" id=\"syT\" style=\"margin-top:10px\"></table></div></div></div>\n<div class=\"p g\" style=\"display:block\" id=\"scSec\"><div class=\"h\"><h2>スタッフ別 利用者別売上</h2><span><span class=\"n\" id=\"scN\"></span>\n<select id=\"scStaff\"></select> <span class=\"seg\" id=\"scSeg\"><button data-k=\"g\" class=\"on\">スタッフ別</button><button data-k=\"l\">一覧表</button></span></span></div>\n<div class=\"kd\" style=\"margin-bottom:8px\"><span id=\"scLeg\"></span></div><div id=\"scBody\"></div></div>\n<div class=\"p g\" style=\"display:block\"><div class=\"h\"><h2>スタッフ × サービス ヒートマップ</h2><span class=\"seg\" id=\"hmSeg\"><button data-k=\"h\" class=\"on\">稼働時間(h)</button><button data-k=\"y\">推計売上(万円)</button></span></div><table class=\"heat\" id=\"heat\"></table></div>\n<div class=\"p note\" id=\"notes\"></div>\n</main>\n<script>/*CHARTJS*/</script>\n<script>const D=/*DATA*/;\nChart.defaults.animation=false;Chart.defaults.font.family='\"Noto Sans CJK JP\",\"Hiragino Sans\",\"Yu Gothic UI\",Meiryo,sans-serif';\nChart.defaults.color='#8b95b0';Chart.defaults.borderColor='#1c2336';\nconst COL={'身体介護':'#00e0ff','家事援助':'#3df5a7','通院等介助':'#4f8bff','居宅介護(内訳不明)':'#59627e','重度訪問介護':'#7b5cff','行動援護':'#ff4fd8','同行援護':'#ffb547','移動支援':'#f97066'};\nconst ML=D.months.map(m=>(+m.slice(5))+'月');\nconst EST=D.months.map(m=>D.est_months.includes(m));\nconst sum=a=>a.reduce((x,y)=>x+(y||0),0);\nconst man=v=>(v/10000).toLocaleString('ja-JP',{maximumFractionDigits:1});\nconst yen=v=>Math.round(v).toLocaleString('ja-JP');\nconst pct=v=>v==null||!isFinite(v)?'—':(v>=0?'+':'')+(v*100).toFixed(1)+'%';\nconst cls=v=>v==null||!isFinite(v)?'':(v>=0?'up':'dn');\nconst S={m:D.months.length-1,svc:'all'};\nfunction salesArr(svc){return svc==='all'?D.sales_m:D.sales_ms[svc]}\nfunction usersArr(svc){return svc==='all'?D.users:D.users_svc[svc]}\nfunction visitArr(svc){const ks=svc==='all'?D.svcB:[svc];return D.months.map((_,i)=>sum(ks.map(k=>D.visit_s[k][i])))}\nfunction hourArr(svc){const ks=svc==='all'?D.svcB:[svc];return D.months.map((_,i)=>sum(ks.map(k=>D.hour_s[k][i])))}\nfunction prevArr(){return S.svc==='all'?D.prev:(D.prev_ms[S.svc]||D.months.map(()=>null))}\nfunction prevYoY(i){const p=prevArr()[i];if(p==null||!p)return null;return salesArr(S.svc)[i]/p-1}\nfunction cumYoY(i){const p=prevArr(),s=salesArr(S.svc);let a=0,b=0;for(let j=0;j<=i;j++){if(p[j]==null)return null;a+=s[j];b+=p[j]}return b?a/b-1:null}\nfunction pvArr(kind){if(S.svc==='all')return kind==='v'?D.prev_vis:D.prev_hrs;const o=kind==='v'?D.prev_vis_s:D.prev_hrs_s;return o&&o[S.svc]?o[S.svc]:D.months.map(()=>null)}\nconst yo=(c,p)=>p==null||!p?null:c/p-1;\nfunction staffYoY(n,i,k){const p=D.prev_staff[n];return p?yo(k==='y'?sum(D.svcs.map(s=>D.staff[n].y[s][i])):k==='h'?sum(D.svcB.map(s=>D.staff[n].h[s][i])):0,p[k][i]):null}\nfunction kpis(){const i=S.m,s=salesArr(S.svc),cur=s[i],pm=i>0?s[i-1]:null,cum=sum(s.slice(0,i+1));\n const u=usersArr(S.svc)[i],v=visitArr(S.svc)[i],h=hourArr(S.svc)[i];\n const k=D.kouhi[i],f=D.futan[i];\n return {cur,mom:pm?cur/pm-1:null,cum,yoy:prevYoY(i),cyoy:cumYoY(i),users:u,visits:v,hours:h,per:u?cur/u:0,k,f,est:EST[i],\n  vy:yo(v,pvArr('v')[i]),hy:yo(h,pvArr('h')[i]),vm:i>0?v/visitArr(S.svc)[i-1]-1:null,hm:i>0?h/hourArr(S.svc)[i-1]-1:null,um:i>0?u-usersArr(S.svc)[i-1]:null}}\nfunction staffRows(i,svc){return Object.entries(D.staff).map(([n,o])=>{const ks=svc==='all'?D.svcB:[svc],ys=svc==='all'?D.svcs:(D.svcs.includes(svc)?[svc]:[]);\n const h=sum(ks.map(k=>o.h[k][i])),v=sum(ks.map(k=>o.v[k][i])),y=sum(ys.map(k=>o.y[k][i])),mh=o.h['移動支援'][i];\n return {n,h,v,y,mh,ph:h>0?y/h:0}}).filter(r=>r.h>0||r.y>0).sort((a,b)=>b.y-a.y||b.h-a.h)}\nfunction staffYear(n){const o=D.staff[n];return {h:D.months.map((_,i)=>sum(D.svcB.map(k=>o.h[k][i]))),v:D.months.map((_,i)=>sum(D.svcB.map(k=>o.v[k][i]))),\n y:D.months.map((_,i)=>sum(D.svcs.map(k=>o.y[k][i])))}}\nconst charts={};function mk(id,cfg){if(charts[id])charts[id].destroy();charts[id]=new Chart(document.getElementById(id),cfg)}\nfunction trendCfg(){const s=salesArr(S.svc);let c=0;const cum=s.map(v=>c+=v);\n return {data:{labels:ML.map((l,i)=>EST[i]?l+'(推計)':l),datasets:[\n {type:'bar',label:'月間売上(万円)',data:s.map(v=>v/1e4),backgroundColor:s.map((_,i)=>EST[i]?'rgba(255,181,71,.45)':(i===S.m?'#00e0ff':'rgba(0,224,255,.45)')),borderColor:s.map((_,i)=>EST[i]?'#ffb547':'transparent'),borderWidth:1,borderDash:[4,3],yAxisID:'y',order:2},\n ...(D.prior_fy?[{type:'line',label:'前年同月(万円)',data:prevArr().map(v=>v==null?null:v/1e4),borderColor:'#ffb547',borderDash:[5,4],pointRadius:2,yAxisID:'y',order:0}]:[]),{type:'line',label:'年度累計(万円)',data:cum.map(v=>v/1e4),borderColor:'#7b5cff',backgroundColor:'#7b5cff',pointRadius:2,tension:.3,yAxisID:'y1',order:1}]},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{y:{position:'left',grid:{color:'#1c2336'}},y1:{position:'right',grid:{display:false}}}}}}\nfunction mixCfg(){const i=S.m;return {type:'doughnut',data:{labels:D.svcs,datasets:[{data:D.svcs.map(s=>D.sales_ms[s][i]),backgroundColor:D.svcs.map(s=>COL[s]),borderColor:'#101524',borderWidth:2}]},\n options:{maintainAspectRatio:false,cutout:'62%',plugins:{legend:{position:'bottom',labels:{boxWidth:10}},tooltip:{callbacks:{label:c=>c.label+' '+man(c.raw)+'万円 ('+(c.raw/sum(c.dataset.data)*100).toFixed(1)+'%)'}}}}}}\nfunction stackCfg(){return {type:'bar',data:{labels:ML,datasets:D.svcs.map(s=>({label:s,data:D.sales_ms[s].map(v=>v/1e4),backgroundColor:COL[s]}))},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{x:{stacked:true},y:{stacked:true,title:{display:true,text:'万円'}}}}}}\nfunction kyoCfg(){const c={'身体':'#00e0ff','家事':'#3df5a7','通院':'#ffb547'};return {type:'bar',data:{labels:ML,datasets:Object.keys(D.kyo_sub).map(s=>({label:s,data:D.kyo_sub[s].map(v=>v/1e4),backgroundColor:c[s]}))},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{x:{stacked:true},y:{stacked:true,title:{display:true,text:'万円'}}}}}}\nfunction clientTop(i,cum,svc){const r=Object.entries(D.clients).map(([k,o])=>{const by={};D.svcs.forEach(s=>{by[s]=cum?sum(o.y[s].slice(0,i+1)):o.y[s][i]});\n const tot=svc==='all'||!D.svcs.includes(svc)?sum(Object.values(by)):by[svc];const p=D.prev_clients[k];\n const pv=p?(cum?(p.slice(0,i+1).some(v=>v==null)?null:sum(p.slice(0,i+1))):p[i]):null;\n return {k,n:o.n,by,tot,yoy:(svc==='all'&&pv)?tot/pv-1:null}}).filter(x=>x.tot>0).sort((a,b)=>b.tot-a.tot);return r.slice(0,20)}\nfunction clientCfg(rows){return {type:'bar',data:{labels:rows.map((r,j)=>(j+1)+'. '+r.n),datasets:D.svcs.map(s=>({label:s,data:rows.map(r=>r.by[s]/1e4),backgroundColor:COL[s]}))},\n options:{indexAxis:'y',maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}},tooltip:{callbacks:{footer:it=>{const r=rows[it[0].dataIndex];return '計 '+man(r.tot)+'万円　前年比 '+pct(r.yoy)}}}},\n scales:{x:{stacked:true,title:{display:true,text:'万円'}},y:{stacked:true,ticks:{autoSkip:false,font:{size:10.5}}}}}}}\nfunction muniCfg(){const i=S.m,e=Object.entries(D.muni).map(([k,v])=>[k,v[i]]).filter(x=>x[1]>0).sort((a,b)=>b[1]-a[1]);\n return {type:'bar',data:{labels:e.map(x=>x[0]),datasets:[{label:'売上(万円)',data:e.map(x=>x[1]/1e4),backgroundColor:'#7b5cff'}]},options:{indexAxis:'y',maintainAspectRatio:false,plugins:{legend:{display:false}}}}}\nfunction staffYearCfg(n){const o=staffYear(n),p=D.prev_staff[n];return {data:{labels:ML,datasets:[...(p?[{type:'line',label:'前年 売上(万円)',data:p.y.map(v=>v/1e4),borderColor:'#ffb547',borderDash:[5,4],yAxisID:'y'}]:[]),{type:'bar',label:'推計売上(万円)',data:o.y.map(v=>v/1e4),backgroundColor:'rgba(0,224,255,.55)',yAxisID:'y'},\n {type:'line',label:'稼働時間(h)',data:o.h,borderColor:'#ff4fd8',backgroundColor:'#ff4fd8',tension:.3,yAxisID:'y1'}]},\n options:{maintainAspectRatio:false,plugins:{legend:{labels:{boxWidth:10}}},scales:{y:{position:'left'},y1:{position:'right',grid:{display:false}}}}}}\nfunction heatHTML(i,metric){const rows=staffRows(i,'all');let mx=0;const cell=(n,s)=>metric==='y'?(D.staff[n].y[s]?D.staff[n].y[s][i]:null):D.staff[n].h[s][i];\n rows.forEach(r=>D.svcB.forEach(s=>{const v=cell(r.n,s);if(v>mx)mx=v}));\n let h='<tr><th>スタッフ</th>'+D.svcB.map(s=>'<th>'+s+'</th>').join('')+'<th>計</th></tr>';\n rows.forEach(r=>{h+='<tr><td class=\"n\">'+r.n+'</td>'+D.svcB.map(s=>{const v=cell(r.n,s);if(v==null)return '<td style=\"color:#59627e\">データなし</td>';\n  const a=mx?v/mx:0;return '<td style=\"background:rgba(0,224,255,'+(0.06+a*0.7).toFixed(2)+');color:'+(a>.5?'#04121a':'#c9d1e6')+'\">'+(v?(metric==='y'?man(v):v.toFixed(1)):'')+'</td>'}).join('')+\n  '<td class=\"t\">'+(metric==='y'?man(r.y):r.h.toFixed(1))+'</td></tr>'});return h}\nconst NOTES=()=>`令和${D.fy-2018}年度版。${D.missing&&D.missing.length?'<b>未登録の月: '+D.missing.join('・')+'（0円で表示）。</b>':''}${D.months.length<12?'<b>年度途中：'+D.months[0]+'〜'+D.months.at(-1)+'の'+D.months.length+'か月分のみ（前年比も同月までで比較）。</b>':''}売上＝請求提出実績①の総費用（提供月基準・小計行除外）。${D.fy}年度（${D.months[0]}〜${D.months[D.months.length-1]}提供分）、年度合計 ${yen(sum(D.sales_m))}円。\n${D.est_months.map(m=>(+m.slice(5))+'月').join('・')}提供分は①未収録のため、③単位数×実績単価（障害福祉${D.ypu.toFixed(2)}円/単位、移動支援${D.ypu_svc&&D.ypu_svc['移動支援']?D.ypu_svc['移動支援'].toFixed(2):'—'}円/単位）で<b>推計</b>。\n①の重複疑い${D.ainfo.dup.groups}組は、返戻・再請求（金額訂正含む）とみなし、各組で最新の提出月の行のみ採用（${D.ainfo.dup.dropped}行除外）。\n各月は「提供月」単位でアップロードされたデータ。月遅れ請求・返戻は、その提供月を再アップロードすると反映。\nスタッフ別売上は推計：③の日別単位（加算は同月の基本行へ比例配分）を②の訪問へ「日付＋利用者＋サービス」で割当（${(D.alloc.exact/D.alloc.total*100).toFixed(1)}%）、不一致分は同月同利用者同サービスの時間比で按分（${(D.alloc.fallback/D.alloc.total*100).toFixed(1)}%）、未割当${(D.alloc.unalloc/D.alloc.total*100).toFixed(1)}%（訪問記録の無い利用者分）。\n居宅介護は①の金額を③の単位比（加算は基本行に比例配分）で身体介護・家事援助・通院等介助（通院は身体伴う/伴わないを合算）に分割。移動支援は移動支援の請求提出実績（総費用・提供月基準）を売上とし、③移動支援明細の日別単位で訪問に割当。時間あたり売上は移動支援の時間を含む。${D.prior_fy?'前年比は'+D.prior_fy+'年度実績（同ダッシュボード方式で算出）との比較。':''}訪問件数・時間は実施済のみ（9月は状況欄なしのため全件）、事務・研修・会議・同行研修・テスト入力は除外。`;\n// ===== スタッフ別 利用者別売上 =====\nconst SCY=r=>sum(r.slice(6));\nfunction scGroups(i,annual){const m={};D.sc.forEach(r=>{if(annual?r[0]>i:r[0]!==i)return;const g=m[r[1]]||(m[r[1]]={n:r[1],cl:{}});\n const c=g.cl[r[2]]||(g.cl[r[2]]={code:r[2],n:D.cnames[r[2]]||r[2],v:0,h:0,hm:0,by:D.svcs.map(()=>0),pv:0,pvok:true});\n c.v+=r[3];c.h+=r[4];c.hm+=r[5];r.slice(6).forEach((y,j)=>c.by[j]+=y);});\n return Object.values(m).map(g=>{const cl=Object.values(g.cl).map(c=>{c.y=sum(c.by);c.ph=c.h>0&&c.y?c.y/c.h:0;\n   if(annual){let p=0,ok=false;for(let j=0;j<=i;j++){const q=D.prev_sc[j+'|'+g.n+'|'+c.code];if(q){p+=q[0];ok=true}}c.yoy=ok&&p?c.y/p-1:null}\n   else{const q=D.prev_sc[i+'|'+g.n+'|'+c.code];c.yoy=q&&q[0]?c.y/q[0]-1:null}return c}).sort((a,b)=>b.y-a.y||b.h-a.h);\n  const t={n:g.n,cl,y:sum(cl.map(c=>c.y)),v:sum(cl.map(c=>c.v)),h:sum(cl.map(c=>c.h)),hm:sum(cl.map(c=>c.hm))};t.ph=t.h>0?t.y/t.h:0;\n  t.yoy=annual?null:staffYoY(g.n,i,'y');if(annual&&D.prev_staff[g.n]){t.yoy=yo(t.y,sum(D.prev_staff[g.n].y.slice(0,i+1)))}return t}).sort((a,b)=>b.y-a.y||b.h-a.h)}\nconst svBar=(by,w)=>{const t=sum(by)||1;return `<div style=\"display:flex;width:${w}px;height:8px;border-radius:4px;overflow:hidden;background:#1c2336\">${D.svcs.map((s,j)=>`<i style=\"width:${by[j]/t*100}%;background:${COL[s]}\"></i>`).join('')}</div>`};\nconst svLegend=()=>D.svcs.map(s=>`<span style=\"white-space:nowrap\"><span style=\"display:inline-block;width:8px;height:8px;border-radius:50%;background:${COL[s]};margin-right:3px\"></span>${s}</span>`).join('　');\n\nlet SCV='g',CL='m',RK='h',HM='h',SEL=null;\nconst selM=document.getElementById('selM'),selS=document.getElementById('selS');\nD.months.forEach((m,i)=>selM.add(new Option(m.replace('-','年')+'月'+(EST[i]?'（推計）':''),i)));selM.value=S.m;\nselS.add(new Option('全サービス','all'));D.svcB.forEach(s=>selS.add(new Option(s,s)));\nselM.onchange=()=>{S.m=+selM.value;render()};selS.onchange=()=>{S.svc=selS.value;render()};\ndocument.querySelectorAll('#rkSeg button').forEach(b=>b.onclick=()=>{RK=b.dataset.k;document.querySelectorAll('#rkSeg button').forEach(x=>x.classList.toggle('on',x===b));render()});\ndocument.querySelectorAll('#scSeg button').forEach(b=>b.onclick=()=>{SCV=b.dataset.k;document.querySelectorAll('#scSeg button').forEach(x=>x.classList.toggle('on',x===b));renderSC()});\nconst scSel=document.getElementById('scStaff');scSel.add(new Option('全スタッフ','all'));Object.keys(D.staff).sort().forEach(n=>scSel.add(new Option(n,n)));scSel.onchange=()=>renderSC();\nfunction renderSC(){const G=scGroups(S.m,false).filter(g=>scSel.value==='all'||g.n===scSel.value);document.getElementById('scLeg').innerHTML=svLegend();\n document.getElementById('scN').textContent=ML[S.m]+'提供分'+(EST[S.m]?'（推計）':'')+'・加算込み推計売上';\n const B=document.getElementById('scBody');\n if(SCV==='g'){const mx=Math.max(1,...G.flatMap(g=>g.cl.map(c=>c.y)));\n  B.innerHTML='<div class=\"scb\" style=\"border:0;background:none\"><div class=\"r hd\" style=\"border:0\"><span>#</span><span>スタッフ ／ 利用者</span><span>売上（推計）</span><span>件数</span><span>時間</span><span>時間単価・内訳</span><span>前年同月比</span></div></div>'+\n  G.map((g,gi)=>`<details class=\"scb\" ${gi<3||scSel.value!=='all'?'open':''}><summary><span>${gi+1}</span><b>${g.n}</b><span><b>${man(g.y)}万円</b></span><span>${g.v}件</span><span>${g.h.toFixed(1)}h</span><span>${g.ph?yen(g.ph)+'円/h':'—'}</span><span class=\"${cls(g.yoy)}\">${pct(g.yoy)}</span></summary>\n  ${g.cl.map(c=>`<div class=\"r\"><span></span><span>${c.n}</span><span class=\"yb\"><span style=\"min-width:52px;text-align:right\">${man(c.y)}万</span><i style=\"width:${c.y/mx*90}px\"></i></span><span>${c.v}</span><span>${c.h.toFixed(1)}${c.hm?'<span class=\"kd\">（移動'+c.hm.toFixed(1)+'）</span>':''}</span><span class=\"yb\">${c.ph?yen(c.ph):'—'} ${svBar(c.by,60)}</span><span class=\"${cls(c.yoy)}\">${pct(c.yoy)}</span></div>`).join('')}</details>`).join('')}\n else{const L=G.flatMap(g=>g.cl.map(c=>({...c,s:g.n}))).sort((a,b)=>b.y-a.y);const mx=Math.max(1,...L.map(c=>c.y));\n  B.innerHTML='<table class=\"st\"><tr><th>#</th><th>スタッフ</th><th>利用者</th><th>売上（推計）</th><th>内訳</th>'+D.svcs.map(s=>'<th>'+s+'</th>').join('')+'<th>件数</th><th>時間</th><th>時間単価</th><th>前年同月比</th></tr>'+\n  L.map((c,j)=>`<tr><td>${j+1}</td><td>${c.s}</td><td>${c.n}</td><td><div class=\"bar\"><span>${man(c.y)}万</span><i style=\"width:${c.y/mx*90}px;background:#00e0ff\"></i></div></td><td>${svBar(c.by,70)}</td>${c.by.map(v=>'<td>'+(v?man(v):'')+'</td>').join('')}<td>${c.v}</td><td>${c.h.toFixed(1)}</td><td>${c.ph?yen(c.ph):'—'}</td><td class=\"${cls(c.yoy)}\">${pct(c.yoy)}</td></tr>`).join('')+'</table>'}}\ndocument.querySelectorAll('#clSeg button').forEach(b=>b.onclick=()=>{CL=b.dataset.k;document.querySelectorAll('#clSeg button').forEach(x=>x.classList.toggle('on',x===b));render()});\ndocument.querySelectorAll('#hmSeg button').forEach(b=>b.onclick=()=>{HM=b.dataset.k;document.querySelectorAll('#hmSeg button').forEach(x=>x.classList.toggle('on',x===b));render()});\ndocument.getElementById('fyChip').textContent='令和'+(D.fy-2018)+'年度（'+D.months[0]+'〜'+D.months.at(-1)+'）';\nfunction card(l,v,d,glow){return `<div class=\"p${glow?' glow':''}\"><div class=\"kl\">${l}</div><div class=\"kv\">${v}</div><div class=\"kd\">${d}</div></div>`}\nfunction render(){const k=kpis(),mv=false,E=k.est?'<span class=\"est\">推計</span>':'';\n document.getElementById('kpis').innerHTML=\n card('月間売上'+E,mv?'データなし':man(k.cur)+'<small>万円</small>',`前月比 <b class=\"${cls(k.mom)}\">${mv?'—':pct(k.mom)}</b>　前年比 <b class=\"${cls(k.yoy)}\">${pct(k.yoy)}</b>`,1)+\n card('年度累計',mv?'データなし':man(k.cum)+'<small>万円</small>',`${ML[0]}〜${ML[S.m]}　前年比 <b class=\"${cls(k.cyoy)}\">${pct(k.cyoy)}</b>`)+\n card('前月比',mv?'—':`<span class=\"${cls(k.mom)}\">${pct(k.mom)}</span>`,mv?'':`前月 ${S.m?man(salesArr(S.svc)[S.m-1]):'—'}万円 → 当月 ${man(k.cur)}万円`)+\n card('公費 ／ 利用者負担',k.est?'—':man(k.k)+'<small>万円</small> / '+man(k.f)+'<small>万円</small>',k.est?'推計月は内訳なし':'公費比率 '+(k.k/(k.k+k.f)*100).toFixed(1)+'%（全サービス）')+\n card('実利用者数',mv?'—':k.users+'<small>人</small>',`前月差 <b class=\"${cls(k.um)}\">${k.um==null?'—':(k.um>=0?'+':'')+k.um}</b>`)+\n card('訪問件数',k.visits.toLocaleString()+'<small>件</small>',`前月比 <b class=\"${cls(k.vm)}\">${pct(k.vm)}</b>　前年比 <b class=\"${cls(k.vy)}\">${pct(k.vy)}</b>`)+\n card('提供時間',k.hours.toLocaleString('ja-JP',{maximumFractionDigits:0})+'<small>h</small>',`前月比 <b class=\"${cls(k.hm)}\">${pct(k.hm)}</b>　前年比 <b class=\"${cls(k.hy)}\">${pct(k.hy)}</b>`)+\n card('利用者1人あたり売上',mv?'—':man(k.per)+'<small>万円</small>','月間売上 ÷ 実利用者数');\n mk('trend',trendCfg());mk('mix',mixCfg());document.getElementById('mixN').textContent=ML[S.m]+'提供分';\n mk('stack',stackCfg());mk('kyo',kyoCfg());const cr=clientTop(S.m,CL==='c',S.svc);mk('cl',clientCfg(cr));\n document.getElementById('clN').textContent=(CL==='c'?ML[0]+'〜'+ML[S.m]+' 累計':ML[S.m]+'提供分')+(EST[S.m]?'（推計含む）':'');\n document.getElementById('clT').innerHTML='<tr><th>#</th><th>利用者</th><th>売上</th><th>サービス内訳</th><th>前年比</th></tr>'+cr.map((r,j)=>`<tr><td>${j+1}</td><td>${r.n}</td><td>${man(r.tot)}万</td><td><div style=\"display:flex;width:120px;height:8px;border-radius:4px;overflow:hidden\">${D.svcs.map(s=>`<i style=\"width:${r.by[s]/sum(Object.values(r.by))*100}%;background:${COL[s]}\"></i>`).join('')}</div></td><td class=\"${cls(r.yoy)}\">${pct(r.yoy)}</td></tr>`).join('');\n const rows=staffRows(S.m,S.svc),rr=[...rows].sort((a,b)=>b[RK]-a[RK]);\n mk('rank',{type:'bar',data:{labels:rr.map(r=>r.n),datasets:[{data:rr.map(r=>RK==='y'?r.y/1e4:RK==='h'?r.h:r.v),backgroundColor:'#00e0ff'}]},options:{indexAxis:'y',maintainAspectRatio:false,plugins:{legend:{display:false}},scales:{y:{ticks:{autoSkip:false,font:{size:10}}}}}});\n const mh=Math.max(...rows.map(r=>r.h),1),my=Math.max(...rows.map(r=>r.y),1);\n document.getElementById('stN').textContent=ML[S.m]+'提供分・'+(S.svc==='all'?'全サービス':S.svc)+'・売上は推計';\n if(!SEL||!D.staff[SEL])SEL=rows[0]&&rows[0].n;\n document.getElementById('stT').innerHTML='<tr><th>スタッフ</th><th>稼働時間</th><th>訪問件数</th><th>推計売上</th><th>時間あたり売上</th><th>売上前年比</th><th>時間前年比</th></tr>'+rows.map(r=>\n `<tr data-n=\"${r.n}\" class=\"${r.n===SEL?'sel':''}\"><td>${r.n}</td><td><div class=\"bar\"><span>${r.h.toFixed(1)}h</span><i style=\"width:${r.h/mh*110}px;background:#ff4fd8\"></i></div></td><td>${r.v}</td>\n <td><div class=\"bar\"><span>${man(r.y)}万</span><i style=\"width:${r.y/my*110}px;background:#00e0ff\"></i></div></td><td>${r.ph?yen(r.ph)+'円':'—'}</td><td class=\"${cls(staffYoY(r.n,S.m,'y'))}\">${pct(staffYoY(r.n,S.m,'y'))}</td><td class=\"${cls(staffYoY(r.n,S.m,'h'))}\">${pct(staffYoY(r.n,S.m,'h'))}</td></tr>`).join('');\n document.querySelectorAll('#stT tr[data-n]').forEach(t=>t.onclick=()=>{SEL=t.dataset.n;render()});\n if(SEL){document.getElementById('sySel').textContent=SEL;mk('sy',staffYearCfg(SEL));const o=staffYear(SEL);\n  document.getElementById('syT').innerHTML='<tr><th></th>'+ML.map(l=>'<th>'+l+'</th>').join('')+'<th>計</th></tr>'+\n  '<tr><td>時間</td>'+o.h.map(v=>'<td>'+v.toFixed(0)+'</td>').join('')+'<td>'+sum(o.h).toFixed(0)+'</td></tr>'+\n  '<tr><td>件数</td>'+o.v.map(v=>'<td>'+v+'</td>').join('')+'<td>'+sum(o.v)+'</td></tr>'+\n  '<tr><td>万円</td>'+o.y.map(v=>'<td>'+man(v)+'</td>').join('')+'<td>'+man(sum(o.y))+'</td></tr>'}\n document.getElementById('heat').innerHTML=heatHTML(S.m,HM);renderSC();\n document.getElementById('notes').innerHTML='<b>注記</b><br>'+NOTES().replace(/\\n/g,'<br>');\n}\nrender();window.__ready=true;\n</script></body></html>\n"};